# Hypothesis: fill by diagonals (main diagonal, then anti-diagonal, etc.)

def fill_by_diagonals(n, values):
    grid = [[0]*n for _ in range(n)]
    idx = 0
    # Main diagonals (top-left to bottom-right direction)
    for j in range(n):
        for i in range(j, -1, -1):
            if idx >= len(values): break
            grid[i][j-i] = values[idx]
            idx += 1
    # Fill remaining
    while idx < len(values):
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 0:
                    grid[i][j] = values[idx]
                    idx += 1
    return grid

